	/*
	* For the #WCCChallenge, theme: "wind."
	* Playing around with my new NavierStokesSolver port to P5js
	*/

function setup() {
	//pixelDensity(1);
  createCanvas(800, 600);
	c = 'rgb(255,255,255)';
	stroke(255);

	frameRate(60);
	numParticles = 2000;
  visc = 0.002;
  velocityScale = 10;
  limitVelocity = 30;
	mScaling = 0.2;

	fluidSolver = new NavierStokesSolver(15);
	particles = new Array(numParticles);
  initParticles();
}

function draw() {
	background(0);
	handleMouseMotion();
	vScale = velocityScale * 60 / frameRate();
  dt = 1 / frameRate();
	fluidSolver.tick(dt, visc);
  drawParticlesPixels();
	// draw letter box
	noStroke();
	fill(100)
	rect(0, height*39/40, width, height*1/40);
	fill(0)
	rect(0, 0, width, height*1/10);
	//rect(0, 0, width/3, height);
	//rect(width/3*2, 0, width/3, height);
	// draw shade
	fill('rgba(0,0,0,0.8)');
	//stroke(255);
	triangle(width/5, 0, width/5, height*19/20, width/2, 0);
	triangle(width*4/5, 0, width*4/5, height*19/20, width/2, 0);
	triangle(width/2, 0, width*2.1/5, height*4/20, width*2.9/5, height*4/20);
	rect(0, 0, width/5, height);
	rect(width*4/5, 0, width/5, height);
	//lamp
	fill('rgba(0,0,0,1)');
	stroke(30);
	line(width/2, height*3/20, width/2, height*2/20, )
	triangle(width/2, height*3/20, width*2.2/5, height*4/20, width*2.8/5, height*4/20);
	noStroke();
	fill('rgba(255,255,240,1)');
	ellipse(width/2, height*4/20, width*2.2/20, height/80-noise(0.05 * frameCount)*10);
	// on the velocity grid
	//fluidSolver.applyForce(1,4+(frameCount % 10)/4,noise(frameCount)*3,noise(frameCount)*1);
	fluidSolver.applyForce(4,2,noise(frameCount)*0.1,0.5);
	fluidSolver.applyForce(5,4,noise(frameCount)*0.2,0.5);
	fluidSolver.applyForce(7,3,noise(frameCount)*0.1,0.5);
	fluidSolver.applyForce(9,10,-noise(frameCount)*1,noise(frameCount)*1);
	fluidSolver.applyForce(1,11,0,noise(frameCount)*0.1);
	fluidSolver.applyForce(7,11,0,noise(frameCount)*0.2);
	fluidSolver.applyForce(13,11,0,noise(frameCount)*0.2);
}

class Particle {
  constructor(x=0, y=0, size=1) {
    this.x = x;
    this.y = y;
		this.size = size;
	}
}

function initParticles() {
  for (let i = 0; i < numParticles; i++) {
    particles[i] = new Particle();
    particles[i].x = random(width);
    particles[i].y = random(height);
		particles[i].size = random([2,3,5]);
  }
}

function drawParticlesPixels() {
	n = fluidSolver.N;
  cellHeight = height / n;
  cellWidth = width / n;
  for (let p of particles) {
    if (p != null) {
      cellX = floor(p.x / cellWidth);
      cellY = floor(p.y / cellHeight);
			  //print([cellX, cellY])
      dx = fluidSolver.getDx(cellX, cellY);
      dy = fluidSolver.getDy(cellX, cellY);
				//print('dx,dy ' + [dx, dy])
      lX = p.x - cellX * cellWidth - cellWidth / 2;
      lY = p.y - cellY * cellHeight - cellHeight / 2;
      	//print('lX,lY ' + [lX, lY])
      if (lX > 0) {
        v = Math.min(n, cellX + 1);
        vf = 1;
      } 
      else {
        v = Math.max(0, cellX - 1);
        vf = -1;
      }
      if (lY > 0) {
        h = Math.min(n, cellY + 1);
        hf = 1;
      } 
      else {
        h = Math.max(0, cellY - 1);
        hf = -1;
      }
			dxv = fluidSolver.getDx(v, cellY);
      dxh = fluidSolver.getDx(cellX, h);
      dxvh = fluidSolver.getDx(v, h);
      dyv = fluidSolver.getDy(v, cellY);
      dyh = fluidSolver.getDy(cellX, h);
      dyvh = fluidSolver.getDy(v, h);
      dx = lerp(lerp(dx, dxv, vf * lX / cellWidth), lerp(dxh, dxvh, vf * lX / cellWidth), hf * lY / cellHeight);
      dy = lerp(lerp(dy, dyv, vf * lX / cellWidth), lerp(dyh, dyvh, vf * lX / cellWidth), hf * lY / cellHeight);
	    p.x += dx * vScale;
      p.y += dy * vScale;
			// limit to domain
      //if (p.x < 0 ) p.x = 0;
			//if (p.x > width ) p.x = width;
      //if (p.y < 0 ) p.y = 0;
      //if (p.y > height ) p.y = height;
			// reseed randomly when escaping 
			if (p.x < 0 || p.x >= width) { p.x = random(width)};
			if (p.y < 0 || p.y >= height) { p.y = random(height/30); p.x = random(width)};
			// reseed bottom escapes in y on top
      //if (p.y < 0 ) p.y = 5;
      //if (p.y > height ) p.y = random(1,height*1/5);
			// particle specific draw
			strokeWeight(p.size);
			stroke(255);
			point(p.x, p.y);
    }
  }
}

function handleMouseMotion() {
	n = fluidSolver.N;
	// only interact when inside the fluid
	if (((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0) & ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width) & ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > 0) & ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < height) ) {
  	mouseDx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - constrain((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width);
  	mouseDy = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - constrain((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height);
  	cellX = floor(n * (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width);
  	cellY = floor(n * (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height);
  	fluidSolver.applyForce(cellX, cellY, mouseDx*mScaling, mouseDy*mScaling);
	}
}
